INSERT INTO `eligibility_rules` VALUES ('RUL-PAN-001','SVC-PAN-NEW-IND','PAN_CITIZEN_RES','Are you an Indian citizen or resident individual applying for an individual PAN?','BOOLEAN_EQUAL','{\"expected\": true, \"field\": \"applicant_category_individual_indian\"}','PROCEED','REROUTE: Foreign entities/citizens must use Form 49AA.','SRC-ITD-RULES','VERIFIED'),('RUL-PAN-002','SVC-PAN-NEW-IND','PAN_NO_EXISTING','Do you already possess a Permanent Account Number (PAN)?','BOOLEAN_EQUAL','{\"expected\": false, \"field\": \"has_existing_pan\"}','PROCEED','REJECT: Possessing more than one PAN is illegal under Section 272B of Income Tax Act (penalty Rs. 10,000).','SRC-ITD-PAN','VERIFIED'),('RUL-PAN-003','SVC-PAN-NEW-IND','PAN_AGE_CONSENT','Is the applicant a minor (under 18 years of age)?','LOGICAL_BRANCH','{\"if_minor\": true, \"requires\": \"REPRESENTATIVE_ASSESSEE\"}','APPLY_VIA_REPRESENTATIVE: Parent/guardian must sign and provide their POI/POA.','PROCEED: Adult applicant signs self.','SRC-ITD-RULES','VERIFIED'),('RUL-PAN-004','SVC-PAN-INSTANT','PAN_INST_AADHAAR','Do you have a valid 12-digit Aadhaar Card?','BOOLEAN_EQUAL','{\"expected\": true, \"field\": \"has_valid_aadhaar\"}','PROCEED','REJECT: Instant e-PAN strictly requires valid Aadhaar.','SRC-ITD-EPAN','VERIFIED'),('RUL-PAN-005','SVC-PAN-INSTANT','PAN_INST_MOBILE','Is your active mobile number linked with your Aadhaar for receiving OTP?','BOOLEAN_EQUAL','{\"expected\": true, \"field\": \"aadhaar_linked_mobile\"}','PROCEED','REJECT: Instant e-PAN requires Aadhaar-based OTP authentication.','SRC-ITD-EPAN','VERIFIED'),('RUL-PAN-006','SVC-PAN-INSTANT','PAN_INST_DOB','Does your Aadhaar card contain your full Date of Birth (DD/MM/YYYY) and not just year?','BOOLEAN_EQUAL','{\"expected\": true, \"field\": \"aadhaar_full_dob\"}','PROCEED','REJECT: Instant e-PAN requires complete DOB on Aadhaar.','SRC-ITD-EPAN','VERIFIED'),('RUL-PAN-007','SVC-PAN-INSTANT','PAN_INST_MAJOR','Are you at least 18 years of age as on date of application?','BOOLEAN_EQUAL','{\"expected\": true, \"field\": \"age_gte_18\"}','PROCEED','REJECT: Minors cannot apply for Instant e-PAN; must apply via Form 49A.','SRC-ITD-EPAN','VERIFIED'),('RUL-UID-001','SVC-UID-ENROL','UID_RESIDENT','Have you resided in India for a period or periods amounting in all to 182 days or more in the 12 months immediately preceding application?','BOOLEAN_EQUAL','{\"expected\": true, \"field\": \"resident_182_days_or_nri_exception\"}','PROCEED','REJECT: Non-residents (except valid Indian passport-holding NRIs) not eligible for resident Aadhaar.','SRC-UIDAI-ACT','VERIFIED'),('RUL-UID-002','SVC-UID-ENROL','UID_NO_EXISTING','Have you ever enrolled for or received an Aadhaar number previously?','BOOLEAN_EQUAL','{\"expected\": false, \"field\": \"has_previous_aadhaar\"}','PROCEED','REJECT: Duplicate enrolment will be rejected during de-duplication by UIDAI. Use Aadhaar retrieval service.','SRC-UIDAI-ACT','VERIFIED'),('RUL-UID-003','SVC-UID-UPD-ADDR','UID_HAS_ACTIVE','Do you possess an active, valid 12-digit Aadhaar number?','BOOLEAN_EQUAL','{\"expected\": true, \"field\": \"has_active_aadhaar\"}','PROCEED','REJECT: Must possess an active Aadhaar number to request updates.','SRC-UIDAI-MYAADHAAR','VERIFIED'),('RUL-UID-004','SVC-UID-UPD-ADDR','UID_ONLINE_OTP','Is your mobile number linked to Aadhaar to receive OTP for online portal login?','LOGICAL_BRANCH','{\"if_true\": \"ONLINE_PORTAL_ELIGIBLE\", \"if_false\": \"PHYSICAL_VISIT_ONLY\"}','PROCEED_ONLINE: Eligible for myAadhaar web update.','REROUTE_OFFLINE: Must visit physical Aadhaar Seva Kendra or Enrolment Centre.','SRC-UIDAI-MYAADHAAR','VERIFIED'),('RUL-UID-005','SVC-UID-UPD-DEMO','UID_NAME_LIMIT','How many times have you previously updated your Name in your Aadhaar record?','NUMERIC_COMPARE','{\"operator\": \"<\", \"max_limit\": 2, \"field\": \"name_updates_count\"}','PROCEED','REJECT: Name can only be updated twice in a lifetime without special UIDAI Regional Office approval.','SRC-UIDAI-CIRCULAR','VERIFIED'),('RUL-UID-006','SVC-UID-UPD-DEMO','UID_DOB_LIMIT','How many times have you previously updated your Date of Birth in your Aadhaar record?','NUMERIC_COMPARE','{\"operator\": \"==\", \"max_limit\": 0, \"field\": \"dob_updates_count\"}','PROCEED','REJECT: Date of Birth can only be updated once in a lifetime (subject to +/- 3 years variance).','SRC-UIDAI-CIRCULAR','VERIFIED'),('RUL-UID-007','SVC-UID-UPD-DEMO','UID_GENDER_LIMIT','Have you previously changed your gender in your Aadhaar record?','BOOLEAN_EQUAL','{\"expected\": false, \"field\": \"gender_update_count_eq_0\"}','PROCEED','REJECT: Gender update is allowed only once in a lifetime.','SRC-UIDAI-CIRCULAR','VERIFIED'),('RUL-VOT-001','SVC-VOTER-NEW','VOT_CITIZEN','Are you an Indian citizen?','BOOLEAN_EQUAL','{\"expected\": true, \"field\": \"citizenship_indian\"}','PROCEED','REJECT: Only Indian citizens are eligible for Form 6.','SRC-ECI-FORM6','VERIFIED'),('RUL-VOT-002','SVC-VOTER-NEW','VOT_AGE','What is your date of birth?','AGE_COMPARE','{\"operator\": \">=\", \"target_age\": 18, \"reference_date\": \"NEXT_QUALIFYING_DATE (1-Jan, 1-Apr, 1-Jul, 1-Oct)\"}','PROCEED','REJECT: Must be at least 18 on or before the next qualifying date.','SRC-ECI-FAQ','VERIFIED'),('RUL-VOT-003','SVC-VOTER-NEW','VOT_RESIDENCE','Do you ordinarily reside in the Assembly Constituency where you are applying?','BOOLEAN_EQUAL','{\"expected\": true, \"field\": \"ordinarily_resident\"}','PROCEED','REJECT: You must apply in the Assembly Constituency of ordinary residence.','SRC-ECI-FAQ','VERIFIED'),('RUL-VOT-004','SVC-VOTER-NEW','VOT_DISQUALIFIED','Are you disqualified from voter registration under Section 16 of RPA 1950 (unsound mind, corrupt practice)?','BOOLEAN_EQUAL','{\"expected\": false, \"field\": \"is_disqualified\"}','PROCEED','REJECT: Disqualified persons cannot be registered in electoral rolls.','SRC-ECI-FORM6','VERIFIED'),('RUL-VOT-005','SVC-VOTER-NEW','VOT_NO_DUPLICATE','Are you already registered as a voter in any Assembly or Parliamentary Constituency in India?','BOOLEAN_EQUAL','{\"expected\": false, \"field\": \"is_already_registered\"}','PROCEED','REROUTE: If already enrolled, submit Form 8 for shifting or correction instead of Form 6.','SRC-ECI-FORM6','VERIFIED');
/*!40000 ALTER TABLE `eligibility_rules` ENABLE KEYS */;
UNLOCK TABLES;

