INSERT INTO `requirement_sources` VALUES ('LNK-001','SRC-ECI-FORM6','SERVICE','SVC-VOTER-NEW','Form 6 governs new registration for general electors.'),('LNK-002','SRC-ECI-FORM6','ELIGIBILITY_RULE','RUL-VOT-001','Page 2 specifies Indian citizenship requirement.'),('LNK-003','SRC-ECI-FAQ','ELIGIBILITY_RULE','RUL-VOT-002','ECI FAQ confirms 4 qualifying dates (1 Jan, 1 Apr, 1 Jul, 1 Oct).'),('LNK-004','SRC-ECI-FORM6','ELIGIBILITY_RULE','RUL-VOT-004','Declaration requires affirming not being disqualified under RPA 1950.'),('LNK-005','SRC-ECI-FORM6','REQUIREMENT_GROUP','GRP-VOT-PHOTO','Form 6 mandates recent unsigned photo with white background.'),('LNK-006','SRC-ECI-FORM6','REQUIREMENT_OPTION','OPT-VOT-002','Form 6 lists municipal birth certificate as accepted age proof.'),('LNK-007','SRC-ECI-FORM6','REQUIREMENT_OPTION','OPT-VOT-003','Form 6 lists Aadhaar card as age and residence proof.'),('LNK-008','SRC-ECI-MYTH','REQUIREMENT_OPTION','OPT-VOT-003','ECI clarifies providing Aadhaar number is voluntary.'),('LNK-009','SRC-ECI-FORM6','REQUIREMENT_OPTION','OPT-VOT-004','Form 6 lists PAN card as age proof; not listed for residence.'),('LNK-010','SRC-ECI-VSP','SUBMISSION_ROUTE','RTE-VOT-001','ECI portal is primary online submission channel.'),('LNK-011','SRC-ITD-RULES','SERVICE','SVC-PAN-NEW-IND','Rule 114 governs Form 49A application for PAN.'),('LNK-012','SRC-ITD-RULES','ELIGIBILITY_RULE','RUL-PAN-001','Rule 114 defines applicant categories for Form 49A vs 49AA.'),('LNK-013','SRC-ITD-PAN','ELIGIBILITY_RULE','RUL-PAN-002','Section 272B prohibits holding multiple PAN cards.'),('LNK-014','SRC-ITD-EPAN','SERVICE','SVC-PAN-INSTANT','Instant e-PAN service on e-filing portal based on Aadhaar.'),('LNK-015','SRC-ITD-EPAN','ELIGIBILITY_RULE','RUL-PAN-004','Instant e-PAN strictly requires valid Aadhaar and linked mobile.'),('LNK-016','SRC-ITD-RULES','REQUIREMENT_OPTION','OPT-PAN-001','Rule 114 lists Aadhaar card as valid POI, POA, and DOB.'),('LNK-017','SRC-ITD-RULES','REQUIREMENT_OPTION','OPT-PAN-002','Rule 114 lists Voter ID (EPIC) as POI, POA, and DOB.'),('LNK-018','SRC-NSDL-PAN','SUBMISSION_ROUTE','RTE-PAN-001','Protean eGov provides paperless e-Sign and physical PAN card delivery.'),('LNK-019','SRC-UIDAI-ACT','SERVICE','SVC-UID-ENROL','Section 3 of Aadhaar Act governs enrolment of resident individuals.'),('LNK-020','SRC-UIDAI-ACT','ELIGIBILITY_RULE','RUL-UID-001','Aadhaar Act defines resident as residing 182+ days in past 12 months.'),('LNK-021','SRC-UIDAI-DOCS','REQUIREMENT_GROUP','GRP-UID-ENR-POI','UIDAI document list establishes permissible POI documents.'),('LNK-022','SRC-UIDAI-DOCS','REQUIREMENT_GROUP','GRP-UID-ENR-POA','UIDAI document list establishes permissible POA documents.'),('LNK-023','SRC-UIDAI-MYAADHAAR','SERVICE','SVC-UID-UPD-ADDR','myAadhaar portal supports online address update via POA or HOF.'),('LNK-024','SRC-UIDAI-CIRCULAR','ELIGIBILITY_RULE','RUL-UID-005','UIDAI circular restricts name changes to max 2 in lifetime.'),('LNK-025','SRC-UIDAI-CIRCULAR','ELIGIBILITY_RULE','RUL-UID-006','UIDAI circular restricts DOB correction to max 1 in lifetime.'),('LNK-026','SRC-UIDAI-ENROL','SUBMISSION_ROUTE','RTE-UID-003','Aadhaar Seva Kendra is mandatory route for Name/DOB demographic update.'),('LNK-027','SRC-IPPB-AADHAAR','SUBMISSION_ROUTE','RTE-UID-005','IPPB provides doorstep Aadhaar mobile number linking via Postman.');
/*!40000 ALTER TABLE `requirement_sources` ENABLE KEYS */;
UNLOCK TABLES;

