LL,'ALL_INDIAN_CITIZENS','Post office savings bank passbook with address.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-016','GRP-PAN-POA','DOC-CREDIT-STMT',NULL,'CREDIT_CARD_HOLDERS','Credit card statement not older than 3 months.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-017','GRP-PAN-POA','DOC-TELEPHONE',NULL,'ALL_INDIAN_CITIZENS','Landline or broadband connection bill not older than 3 months.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-018','GRP-PAN-POA','DOC-PROPERTY-TAX',NULL,'PROPERTY_OWNERS','Property tax assessment order not older than 1 year.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-019','GRP-PAN-POA','DOC-DOMICILE',NULL,'ALL_INDIAN_CITIZENS','Domicile certificate issued by State Government.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-020','GRP-PAN-DOB','DOC-BIRTH',NULL,'ALL_INDIAN_CITIZENS','Birth certificate from competent municipal / local body authority.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-021','GRP-PAN-DOB','DOC-EDU',NULL,'MATRICULATES','Matriculation / Class X marksheet or board certificate with DOB.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-022','GRP-PAN-DOB','DOC-AADHAAR',NULL,'ALL_INDIAN_CITIZENS','Aadhaar card issued by UIDAI displaying complete DOB.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-023','GRP-PAN-DOB','DOC-PASSPORT',NULL,'ALL_INDIAN_CITIZENS','Valid Passport.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-024','GRP-PAN-DOB','DOC-DL',NULL,'ALL_INDIAN_CITIZENS','Driving Licence.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-025','GRP-PAN-DOB','DOC-PENSION',NULL,'PENSIONERS','Pension Payment Order displaying date of birth.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-026','GRP-PAN-PHOTO','DOC-PHOTO-SPEC',NULL,'ALL_INDIAN_CITIZENS','Two passport size color photos (3.5 x 2.5 cm) and applicant signature.','VERIFIED','SRC-ITD-PAN'),('OPT-PAN-027','GRP-PAN-INST-EKYC','DOC-AADHAAR','RUL-PAN-004','INDIVIDUAL_ADULT','Direct e-KYC authentication via Aadhaar OTP (no paper or manual upload required).','VERIFIED','SRC-ITD-EPAN'),('OPT-UID-001','GRP-UID-ENR-POI','DOC-PASSPORT',NULL,'ALL_RESIDENTS',