,('OPT-UID-016','GRP-UID-ENR-DOB','DOC-PAN',NULL,'ALL_RESIDENTS','PAN Card.','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-017','GRP-UID-ENR-DOB','DOC-EDU',NULL,'MATRICULATES','Class X / XII marksheet containing date of birth.','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-018','GRP-UID-UPD-POA','DOC-PASSPORT','RUL-UID-003','ALL_RESIDENTS','Passport with updated address.','VERIFIED','SRC-UIDAI-MYAADHAAR'),('OPT-UID-019','GRP-UID-UPD-POA','DOC-UTIL','RUL-UID-003','ALL_RESIDENTS','Electricity / water / piped gas bill (not older than 3 months).','VERIFIED','SRC-UIDAI-MYAADHAAR'),('OPT-UID-020','GRP-UID-UPD-POA','DOC-BANK-STMT','RUL-UID-003','ALL_RESIDENTS','Bank account statement with stamp and signature (not older than 3 months).','VERIFIED','SRC-UIDAI-MYAADHAAR'),('OPT-UID-021','GRP-UID-UPD-POA','DOC-RENT','RUL-UID-003','TENANTS','Registered rent agreement registered with Sub-Registrar.','VERIFIED','SRC-UIDAI-MYAADHAAR'),('OPT-UID-022','GRP-UID-UPD-POA','DOC-HOF-DECL','RUL-UID-003','FAMILY_DEPENDENT','Head of Family (HOF) consent and declaration where applicant lacks document.','VERIFIED','SRC-UIDAI-MYAADHAAR'),('OPT-UID-023','GRP-UID-UPD-POI','DOC-PASSPORT','RUL-UID-005','ALL_RESIDENTS','Passport in updated name.','VERIFIED','SRC-UIDAI-CIRCULAR'),('OPT-UID-024','GRP-UID-UPD-POI','DOC-PAN','RUL-UID-005','ALL_RESIDENTS','PAN Card in updated name.','VERIFIED','SRC-UIDAI-CIRCULAR'),('OPT-UID-025','GRP-UID-UPD-POI','DOC-GAZETTE','RUL-UID-005','MAJOR_NAME_CHANGE','Official Gazette Notification for complete legal name change.','VERIFIED','SRC-UIDAI-CIRCULAR'),('OPT-UID-026','GRP-UID-UPD-POI','DOC-MARRIAGE-CERT','RUL-UID-005','AFTER_MARRIAGE','Marriage Certificate for post-marriage change in name / surname.','VERIFIED','SRC-UIDAI-CIRCULAR'),('OPT-UID-027','GRP-UID-UPD-DOB','DOC-BIRTH','RUL-UID-006','ALL_RESIDENTS','Birth certificate from competent municipal authority (UIDAI restricted list).','VERIFIED','SRC-UIDAI-CIRCULAR'),('OPT-UID-028','GRP-UID-UPD-DOB','DOC-PASSPORT','RUL-UID-006','