INSERT INTO `applications` VALUES ('APP-2026-0001','USR-GJ-DEMO-01','SVC-VOTER-NEW',NULL,'online','REQUIREMENTS_PENDING',NULL,'2026-10-28 11:00:00',NULL,NULL,'Citizen completed DigiSahay eligibility screening for Voter ID Form 6. Age proof document uploaded; waiting for resident to upload accepted Proof of Residence before proceeding to official ECI portal.'),('APP-2026-0002','USR-GJ-DEMO-01','SVC-UID-UPD-BIO','2026/00100/12345','hybrid','READY_TO_APPLY',NULL,'2026-10-28 14:18:22','UIDAI Official ASK Booking Slip','APT-2026-0001','Appointment successfully booked at UIDAI ASK Ahmedabad (APT-2026-0001). Citizen checklist validated. Pending physical visit on 2026-11-05 for biometric capture.'),('APP-2026-0003','USR-GJ-DEMO-02','SVC-PAN-INSTANT','ITD-EPAN-GJ-409128','online','APPROVED','2026-10-25 10:15:00','2026-10-25 10:25:00','Income Tax e-Filing Instant e-PAN Portal',NULL,'Instant e-PAN successfully allotted through official ITD e-Filing portal via Aadhaar e-KYC. Simulated verification tracking in DigiSahay prototype.'),('APP-2026-0004','USR-GJ-DEMO-02','SVC-UID-UPD-DEMO',NULL,'hybrid','DRAFT',NULL,'2026-10-29 09:30:00',NULL,'APT-2026-0002','Draft checklist for Aadhaar Name correction. Appointment requested on DigiSahay (APT-2026-0002, PENDING official booking). Citizen must verify gazette/marriage certificate requirement.'),('APP-2026-0005','USR-GJ-DEMO-03','SVC-VOTER-NEW','S06123456789','online','UNDER_REVIEW','2026-10-12 16:30:00','2026-10-20 11:00:00','ECI Voters Service Portal (voters.eci.gov.in)',NULL,'Form 6 submitted directly by citizen on ECI portal. Official ECI reference S06123456789 logged into DigiSahay for milestone tracking. BLO field verification pending.'),('APP-2026-0006','USR-GJ-DEMO-04','SVC-UID-ENROL','1001/20002/30003','hybrid','SUBMITTED','2026-10-15 12:10:00','2026-10-18 14:00:00','UIDAI Enrolment Acknowledgement Slip','APT-2026-0006','Resident attended Vadodara ASK appointment (APT-2026-0005). 28-digit Enrolment ID logged. UIDAI backend packet validation in progress.'),('APP-2026-0007','USR-GJ-DEMO-05','SVC-PAN-NEW-IND','N-884920194820','offline-assisted','REJECTED','2026-09-10 11:00:00','2026-09-18 15:30:00','Protean TIN-FC Application Status Portal',NULL,'Paper application submitted at TIN-FC rejected by NSDL back-office due to discrepancy between name on Proof of Identity and PAN Form 49A. DigiSahay logged reason for corrective re-filing.'),('APP-2026-7B1F8A','USR-EACF7F493656','SVC-VOTER-NEW','DIGI/VOTERNEW/20261102/7B1F8A','ONLINE_ASSISTED','READY_TO_APPLY','2026-11-02 06:12:36','2026-11-02 06:12:36','DigiSahay Direct Citizen Application Preparation',NULL,'{\"full_name\": \"Test Citizen Patel\", \"guardian_name\": \"Somabhai Patel\", \"dob\": \"1995-05-15\", \"gender\": \"Male\", \"mobile\": \"9876543210\", \"email\": \"testcitizen@example.com\", \"address\": \"101 Sardar Patel Colony, Navrangpura\", \"district\": \"Ahmedabad\", \"pincode\": \"380009\", \"application_mode\": \"ONLINE_ASSISTED\", \"additional_notes\": \"\"}'),('APP-DEMO-VOTER-001','USR-543D84F5DC1B','SVC-VOTER-NEW',NULL,'ONLINE','READY_TO_APPLY',NULL,'2026-11-01 17:06:34',NULL,NULL,NULL);
