INSERT INTO `center_services` VALUES ('CSV-ASK-001','CTR-GJ-ASK-001','SVC-UID-ENROL',1,1,'official_online_booking','https://appointments.uidai.gov.in/','UIDAI ASK Ahmedabad Portal Schedule','VERIFIED','2026-10-27 00:00:00','Full enrolment kit operational with token system. Online appointment or kiosk walk-in.'),('CSV-ASK-002','CTR-GJ-ASK-001','SVC-UID-UPD-BIO',1,1,'official_online_booking','https://appointments.uidai.gov.in/','UIDAI ASK Ahmedabad Portal Schedule','VERIFIED','2026-10-27 00:00:00','Biometric updates including mandatory child updates (5/15 yrs), iris scan, photo, and 10-fingerprint updates.'),('CSV-ASK-003','CTR-GJ-ASK-001','SVC-UID-UPD-DEMO',1,1,'official_online_booking','https://appointments.uidai.gov.in/','UIDAI ASK Ahmedabad Portal Schedule','VERIFIED','2026-10-27 00:00:00','In-person demographic update for Name, DOB, Gender with POI/DOB physical document verification.'),('CSV-ASK-004','CTR-GJ-ASK-001','SVC-UID-UPD-MOB',1,1,'official_online_booking','https://appointments.uidai.gov.in/','UIDAI ASK Ahmedabad Portal Schedule','VERIFIED','2026-10-27 00:00:00','Aadhaar mobile linking/update and email ID linkage. Requires resident biometric authentication.'),('CSV-ASK-005','CTR-GJ-ASK-001','SVC-UID-DOC-UPD',1,1,'official_online_booking','https://appointments.uidai.gov.in/','UIDAI ASK Ahmedabad Portal Schedule','VERIFIED','2026-10-27 00:00:00','In-person submission for 10-year periodic document re-validation (POI and POA) under Regulation 16A.'),('CSV-ASK-006','CTR-GJ-ASK-002','SVC-UID-ENROL',1,1,'official_online_booking','https://appointments.uidai.gov.in/','UIDAI ASK Vadodara Schedule','VERIFIED','2026-10-27 00:00:00','New enrolment free of government charge at Vadodara ASK.'),('CSV-ASK-007','CTR-GJ-ASK-002','SVC-UID-UPD-BIO',1,1,'official_online_booking','https://appointments.uidai.gov.in/','UIDAI ASK Vadodara Schedule','VERIFIED','2026-10-27 00:00:00','Mandatory and voluntary biometric update workstations.'),('CSV-ASK-008','CTR-GJ-ASK-002','SVC-UID-UPD-DEMO',1,1,'official_online_booking','https://appointments.uidai.gov.in/','UIDAI ASK Vadodara Schedule','VERIFIED','2026-10-27 00:00:00','Demographic corrections with original documentary proof.'),('CSV-ASK-009','CTR-GJ-ASK-002','SVC-UID-UPD-MOB',1,1,'official_online_booking','https://appointments.uidai.gov.in/','UIDAI ASK Vadodara Schedule','VERIFIED','2026-10-27 00:00:00','Mobile and email update without document requirement (biometric auth only).'),('CSV-ASK-010','CTR-GJ-ASK-003','SVC-UID-ENROL',1,1,'official_online_booking','https://appointments.uidai.gov.in/','UIDAI ASK Surat Schedule','VERIFIED','2026-10-27 00:00:00','New Aadhaar enrolment at Majura Gate center.'),('CSV-ASK-011','CTR-GJ-ASK-003','SVC-UID-UPD-BIO',1,1,'official_online_booking','https://appointments.uidai.gov.in/','UIDAI ASK Surat Schedule','VERIFIED','2026-10-27 00:00:00','Biometric updates for Surat district residents.'),('CSV-ASK-012','CTR-GJ-ASK-003','SVC-UID-UPD-DEMO',1,1,'official_online_booking','https://appointments.uidai.gov.in/','UIDAI ASK Surat Schedule','VERIFIED','2026-10-27 00:00:00','Demographic corrections and in-person verification.'),('CSV-DEMO-001','DEMO-CENTER-001','SVC-VOTER-NEW',1,0,'walk-in',NULL,'Simulated Jan Seva Kendra Charter','DEMO_ONLY','2026-10-27 00:00:00','Demonstration record: citizen guidance desk for voter registration intake.'),('CSV-DEMO-002','DEMO-CENTER-001','SVC-PAN-NEW-IND',1,0,'walk-in',NULL,'Simulated Jan Seva Kendra Charter','DEMO_ONLY','2026-10-27 00:00:00','Demonstration record: assisted PAN card physical paperwork facilitation.'),('CSV-ERO-001','CTR-GJ-ERO-001','SVC-VOTER-NEW',1,0,'walk-in',NULL,'CEO Gujarat ERO Directory','VERIFIED','2026-10-27 00:00:00','Physical submission of Form 6 for Assembly Constituency 44 (Ellisbridge). Walk-in during office hours. No prior appointment required.'),('CSV-PO-001','CTR-GJ-PO-001','SVC-UID-ENROL',1,0,'walk-in',NULL,'India Post Aadhaar Centers Listing','VERIFIED','2026-10-27 00:00:00','New enrolment available via daily queue tokens issued in morning. First-come first-served walk-in.'),('CSV-PO-002','CTR-GJ-PO-001','SVC-UID-UPD-BIO',1,0,'walk-in',NULL,'India Post Aadhaar Centers Listing','VERIFIED','2026-10-27 00:00:00','Biometric update facility for children and adults at dedicated postal counter.'),('CSV-PO-003','CTR-GJ-PO-001','SVC-UID-UPD-MOB',1,0,'walk-in',NULL,'India Post Aadhaar Centers Listing','VERIFIED','2026-10-27 00:00:00','Aadhaar mobile linking counter. Quick biometric auth.'),('CSV-TIN-001','CTR-GJ-TIN-001','SVC-PAN-NEW-IND',1,0,'walk-in',NULL,'Protean TIN Facility Directory','VERIFIED','2026-10-27 00:00:00','Assisted Form 49A physical submission, verification of original documents, and biometrics/token acknowledgment generation.');
