INSERT INTO `document_types` VALUES ('DOC-AADHAAR','Aadhaar Card / Letter / e-Aadhaar','Identity & Residence','12-digit unique identity issued by UIDAI.','Self-attested copy (masked Aadhaar recommended for private third-parties)','PDF/JPEG <= 2MB','Accepted for Voter ID (DOB & POA), PAN (POI, POA, DOB). On Voter ID, providing Aadhaar number is voluntary.',1,'VERIFIED'),('DOC-ARMS','Arms Licence','Licensing','Arms Licence with photograph issued under Arms Act.','Self-attested copy','PDF/JPEG <= 2MB','Accepted as POI for PAN and Aadhaar.',1,'VERIFIED'),('DOC-BANK-STMT','Bank Account Statement','Financial','Computerised statement of bank account on bank letterhead with official seal & signature.','Original statement (not older than 3 months)','PDF/JPEG <= 2MB','Accepted as POA for PAN and Aadhaar (not older than 3 months).',1,'VERIFIED'),('DOC-BIRTH','Birth Certificate','Civil Registration','Certificate issued by Municipal Corporation, Local Body, or Registrar of Births & Deaths.','Self-attested copy (original for physical verification)','PDF/JPEG <= 2MB','Must be issued by statutory competent authority.',1,'VERIFIED'),('DOC-CGHS','CGHS / ECHS / State Health Scheme Card','Health / Welfare','Health scheme card containing photograph of beneficiary.','Self-attested copy','PDF/JPEG <= 2MB','Accepted as POI in PAN and Aadhaar.',1,'VERIFIED'),('DOC-CREDIT-STMT','Credit Card Statement','Financial','Statement of credit card account.','Not older than 3 months','PDF/JPEG <= 2MB','Accepted as POA for PAN card only (not listed for Voter ID).',1,'VERIFIED'),('DOC-DL','Driving Licence','Transport / Identity','Driving Licence issued by State Licensing Authority / RTO.','Self-attested copy (original to show)','PDF/JPEG <= 2MB','Accepted as Age Proof in Voter ID, POI/POA in PAN, and POI in UIDAI (if chip/smart card with photo).',1,'VERIFIED'),('DOC-DOMICILE','Domicile / Residence / Nativity Certificate','Government Certificate','Certificate of domicile/residence issued by State Government / Tehsildar.','Self-attested copy','PDF/JPEG <= 2MB','Accepted as POA for PAN and Aadhaar.',1,'VERIFIED'),('DOC-EDU','Class X / XII Board Certificate / Marksheet','Educational','Certificate or marksheet issued by CBSE, ICSE, or State Education Board containing DOB.','Self-attested copy','PDF/JPEG <= 2MB','Must clearly display candidate date of birth.',1,'VERIFIED'),('DOC-GAZETTE','Gazette Notification for Name Change','Legal / Official','Official Gazette of Central or State Government publishing legal name change.','Original or certified copy','PDF <= 2MB','Mandatory for major name change in Aadhaar or PAN when name is completely altered.',1,'VERIFIED'),('DOC-HOF-DECL','Head of Family (HOF) Self-Declaration','UIDAI Prescribed Format','Declaration by Head of Family confirming relationship and consenting to share address.','Online OTP consent or physical signed Annexure','Portal / PDF','Applicable for Aadhaar address update when family member lacks address proof in own name.',1,'VERIFIED'),('DOC-LAND','Land Ownership Record / Kisan Bahi','Revenue / Property','Revenue Department record of land rights or Kisan Passbook.','Self-attested copy','PDF/JPEG <= 2MB','Accepted for Voter ID residence proof; UIDAI Kisan Passbook with photo.',1,'VERIFIED'),('DOC-MARRIAGE-CERT','Marriage Certificate','Civil Registration','Marriage Certificate issued by Registrar of Marriages containing applicant name & photo.','Self-attested copy','PDF <= 2MB','Accepted for change of surname/name after marriage in PAN and Aadhaar.',1,'VERIFIED'),('DOC-PAN','PAN Card','Tax Identity','Permanent Account Number card issued by Income Tax Department.','Self-attested copy','PDF/JPEG <= 2MB','Accepted as Age Proof in Voter ID, and POI in various services. NOT accepted as standard Proof of Address.',1,'VERIFIED'),('DOC-PASSBOOK','Bank / Post Office Passbook','Financial','Passbook of Nationalised / Scheduled Commercial Bank or Post Office with photo & address stamp.','Self-attested copy of front page / transaction page','PDF/JPEG <= 2MB','Must have bank stamp and signature on photograph and address details.',1,'VERIFIED'),('DOC-PASSPORT','Indian Passport','Citizenship & Travel','Valid Passport of the Republic of India issued by Ministry of External Affairs.','Self-attested copy of front and back pages','PDF/JPEG <= 2MB','Universally accepted as POI, POA, and Proof of DOB across Voter ID, PAN, and Aadhaar.',1,'VERIFIED'),('DOC-PENSION','Pension Payment Order (PPO) / Ex-Servicemen Card','Pension / Defence','PPO or Pensioner card issued to retired government / defence personnel with photo.','Self-attested copy','PDF/JPEG <= 2MB','Accepted as POI and DOB in PAN; POI in Aadhaar.',1,'VERIFIED'),('DOC-PHOTO-SPEC','Passport Size Photograph (Physical / Digital)','Photograph','Color photograph with white background, front-facing.','Physical prints or digital upload (20KB - 50KB)','JPEG <= 50KB','Mandatory for physical form submissions and online portal uploads.',1,'VERIFIED'),('DOC-PROPERTY-TAX','Property Tax Receipt','Municipal','Municipal corporation tax receipt for current tax assessment.','Not older than 1 year','PDF/JPEG <= 2MB','Accepted as POA for PAN and Aadhaar.',1,'VERIFIED'),('DOC-RATION','Ration Card / PDS Card','Social Welfare','Public Distribution System card issued by Food & Civil Supplies Department.','Self-attested copy','PDF/JPEG <= 2MB','Accepted for PAN (POI/POA with photo), Aadhaar (POI/POA/POR with family photo).',1,'VERIFIED'),('DOC-RENT','Registered Rent / Lease Agreement','Legal / Property','Registered agreement between landlord and tenant registered with Sub-Registrar.','Copy of registered deed','PDF/JPEG <= 2MB','Must be registered with Sub-Registrar (unregistered notary agreements are generally rejected).',1,'VERIFIED'),('DOC-SALE','Registered Sale Deed','Legal / Property','Registered title conveyance / sale deed in respect of owned house/property.','Copy of registered deed','PDF/JPEG <= 2MB','Must be registered with State Registration Department.',1,'VERIFIED'),('DOC-TELEPHONE','Landline / Broadband Postpaid Telephone Bill','Utilities','Postpaid landline or broadband bill from BSNL/MTNL/airtel/Jio etc.','Not older than 3 months','PDF/JPEG <= 2MB','Accepted as POA for PAN and Aadhaar (not older than 3 months).',1,'VERIFIED'),('DOC-UIDAI-STDFORM','UIDAI Standard Certificate (MP/MLA/Gazetted Officer/Tehsildar)','UIDAI Prescribed Format','Certificate on UIDAI prescribed Annexure-I format with photo cross-signed and stamped.','Original within 3 months of validity','PDF/JPEG <= 2MB','Valid ONLY on UIDAI official format. Valid for 3 months from date of issue.',1,'VERIFIED'),('DOC-UTIL','Utility Bill (Electricity / Water / Piped Gas)','Utilities','Utility connection bill in applicant or immediate parent/spouse name.','Copy of recent bill (at least 1 yr old for Voter ID; not older than 3 months for PAN/UIDAI)','PDF/JPEG <= 2MB','Voter ID requires connection of at least 1 year. PAN and Aadhaar require bill to be under 3 months old.',1,'VERIFIED'),('DOC-VOTER-ID','Voter ID Card (EPIC)','Electoral Identity','Elector Photo Identity Card issued by Election Commission of India.','Self-attested copy','PDF/JPEG <= 2MB','Accepted as POI, POA, and DOB for PAN (Rule 114) and POI/POA for Aadhaar Enrolment/Update.',1,'VERIFIED');
/*!40000 ALTER TABLE `document_types` ENABLE KEYS */;
UNLOCK TABLES;

