LOCK TABLES `requirement_groups` WRITE;
/*!40000 ALTER TABLE `requirement_groups` DISABLE KEYS */;
INSERT INTO `requirement_groups` VALUES ('GRP-PAN-DOB','SVC-PAN-NEW-IND','Proof of Date of Birth (DOB)','Document establishing applicant exact date of birth in accordance with Rule 114.','CHOOSE_ONE',1,1,NULL,'VERIFIED'),('GRP-PAN-INST-EKYC','SVC-PAN-INSTANT','Aadhaar OTP e-KYC Data','Demographic details and digital photo pulled directly and automatically from UIDAI repository via OTP.','ALL',1,1,'RUL-PAN-004','VERIFIED'),('GRP-PAN-PHOTO','SVC-PAN-NEW-IND','Applicant Photographs & Signature','Two recent passport size color photos (3.5 x 2.5 cm) and applicant signature/thumb impression.','ALL',2,2,NULL,'VERIFIED'),('GRP-PAN-POA','SVC-PAN-NEW-IND','Proof of Address (POA)','Document establishing applicant residential address in accordance with Rule 114.','CHOOSE_ONE',1,1,NULL,'VERIFIED'),('GRP-PAN-POI','SVC-PAN-NEW-IND','Proof of Identity (POI)','Document establishing identity of the applicant in accordance with Rule 114 of IT Rules 1962.','CHOOSE_ONE',1,1,NULL,'VERIFIED'),('GRP-UID-ENR-BIO','SVC-UID-ENROL','Biometric Capture','Live capture of facial image, 10 iris scans, and 10 fingerprint scans at enrolment centre (for applicants aged 5+).','ALL',1,1,NULL,'VERIFIED'),('GRP-UID-ENR-DOB','SVC-UID-ENROL','Proof of Date of Birth (DOB)','Official DOB document from UIDAI approved list (mandatory for Verified DOB status).','CHOOSE_ONE',1,1,NULL,'VERIFIED'),('GRP-UID-ENR-POA','SVC-UID-ENROL','Proof of Address (POA)','Official POA document containing applicant name and residential address from UIDAI approved list.','CHOOSE_ONE',1,1,NULL,'VERIFIED'),('GRP-UID-ENR-POI','SVC-UID-ENROL','Proof of Identity (POI)','Official POI document containing applicant name and photograph from UIDAI approved list.','CHOOSE_ONE',1,1,NULL,'VERIFIED'),('GRP-UID-ENR-POR','SVC-UID-ENROL','Proof of Relationship (POR)','Document establishing relationship with Head of Family (HOF) / Parent (mandatory for child <5 yrs or HOF-based enrolment).','CONDITIONAL',0,1,'RUL-UID-001','VERIFIED'),('GRP-UID-UPD-BIO-MAND','SVC-UID-UPD-BIO','Biometric Capture (Biometric Update)','In-person capture of fingerprints, iris scans, and updated photograph at Aadhaar Seva Kendra.','ALL',1,1,NULL,'VERIFIED'),('GRP-UID-UPD-DOB','SVC-UID-UPD-DEMO','Proof of Date of Birth for DOB Update','Strictly Birth Certificate issued by municipal body or Indian Passport (UIDAI restricted list for DOB update).','CHOOSE_ONE',1,1,'RUL-UID-006','VERIFIED'),('GRP-UID-UPD-MOB-BIO','SVC-UID-UPD-MOB','Biometric Authentication for Mobile Link','In-person fingerprint / iris scan to authenticate identity before mobile/email is registered in database.','ALL',1,1,NULL,'VERIFIED'),('GRP-UID-UPD-POA','SVC-UID-UPD-ADDR','Proof of Address (POA) for Update','Document verifying new residential address; or HOF Self-Declaration where applicant has no POA in own name.','CHOOSE_ONE',1,1,'RUL-UID-003','VERIFIED'),('GRP-UID-UPD-POI','SVC-UID-UPD-DEMO','Proof of Identity (POI) for Name Update','Valid POI document in applicant new legal name, plus gazette notification if complete name change.','CHOOSE_ONE',1,1,'RUL-UID-005','VERIFIED'),('GRP-VOT-AGE','SVC-VOTER-NEW','Proof of Date of Birth (Age Proof)','Document proving applicant date of birth. Mandatory where applicable under Form 6 instructions.','CHOOSE_ONE',1,1,'RUL-VOT-002','VERIFIED'),('GRP-VOT-OPT','SVC-VOTER-NEW','Voluntary and Optional Information','Aadhaar number (voluntary), mobile number, email, and disability category (if applicable).','OPTIONAL',0,4,NULL,'VERIFIED'),('GRP-VOT-PHOTO','SVC-VOTER-NEW','Applicant Photograph','Recent unsigned colour passport-size photograph (4.5 x 3.5 cm, frontal face, white background).','ALL',1,1,NULL,'VERIFIED'),('GRP-VOT-RES','SVC-VOTER-NEW','Proof of Ordinary Residence','Document proving applicant ordinary residence at the current address in the constituency.','CHOOSE_ONE',1,1,'RUL-VOT-003','VERIFIED');
/*!40000 ALTER TABLE `requirement_groups` ENABLE KEYS */;
UNLOCK TABLES;

