INSERT INTO `requirements` VALUES ('OPT-PAN-001','GRP-PAN-POI','DOC-AADHAAR',NULL,'ALL_INDIAN_CITIZENS','Aadhaar card issued by UIDAI.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-002','GRP-PAN-POI','DOC-VOTER-ID',NULL,'ALL_INDIAN_CITIZENS','Elector Photo Identity Card (EPIC).','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-003','GRP-PAN-POI','DOC-PASSPORT',NULL,'ALL_INDIAN_CITIZENS','Valid Indian Passport.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-004','GRP-PAN-POI','DOC-DL',NULL,'ALL_INDIAN_CITIZENS','Valid Driving Licence.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-005','GRP-PAN-POI','DOC-RATION',NULL,'ALL_INDIAN_CITIZENS','Ration card having photograph of the applicant.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-006','GRP-PAN-POI','DOC-ARMS',NULL,'ALL_INDIAN_CITIZENS','Arms licence having photograph of applicant.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-007','GRP-PAN-POI','DOC-PENSION',NULL,'PENSIONERS','Pensioner card having photograph of applicant.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-008','GRP-PAN-POI','DOC-CGHS',NULL,'GOVT_EMPLOYEES','Central Government Health Scheme card or ECHS card.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-009','GRP-PAN-POA','DOC-AADHAAR',NULL,'ALL_INDIAN_CITIZENS','Aadhaar card having address of the applicant.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-010','GRP-PAN-POA','DOC-VOTER-ID',NULL,'ALL_INDIAN_CITIZENS','Elector Photo Identity Card having applicant address.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-011','GRP-PAN-POA','DOC-PASSPORT',NULL,'ALL_INDIAN_CITIZENS','Valid Passport.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-012','GRP-PAN-POA','DOC-DL',NULL,'ALL_INDIAN_CITIZENS','Driving Licence.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-013','GRP-PAN-POA','DOC-UTIL',NULL,'ALL_INDIAN_CITIZENS','Electricity, water, or piped gas bill not older than 3 months.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-014','GRP-PAN-POA','DOC-BANK-STMT',NULL,'ALL_INDIAN_CITIZENS','Bank account statement not older than 3 months.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-015','GRP-PAN-POA','DOC-PASSBOOK',NULL,'ALL_INDIAN_CITIZENS','Post office savings bank passbook with address.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-016','GRP-PAN-POA','DOC-CREDIT-STMT',NULL,'CREDIT_CARD_HOLDERS','Credit card statement not older than 3 months.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-017','GRP-PAN-POA','DOC-TELEPHONE',NULL,'ALL_INDIAN_CITIZENS','Landline or broadband connection bill not older than 3 months.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-018','GRP-PAN-POA','DOC-PROPERTY-TAX',NULL,'PROPERTY_OWNERS','Property tax assessment order not older than 1 year.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-019','GRP-PAN-POA','DOC-DOMICILE',NULL,'ALL_INDIAN_CITIZENS','Domicile certificate issued by State Government.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-020','GRP-PAN-DOB','DOC-BIRTH',NULL,'ALL_INDIAN_CITIZENS','Birth certificate from competent municipal / local body authority.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-021','GRP-PAN-DOB','DOC-EDU',NULL,'MATRICULATES','Matriculation / Class X marksheet or board certificate with DOB.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-022','GRP-PAN-DOB','DOC-AADHAAR',NULL,'ALL_INDIAN_CITIZENS','Aadhaar card issued by UIDAI displaying complete DOB.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-023','GRP-PAN-DOB','DOC-PASSPORT',NULL,'ALL_INDIAN_CITIZENS','Valid Passport.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-024','GRP-PAN-DOB','DOC-DL',NULL,'ALL_INDIAN_CITIZENS','Driving Licence.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-025','GRP-PAN-DOB','DOC-PENSION',NULL,'PENSIONERS','Pension Payment Order displaying date of birth.','VERIFIED','SRC-ITD-RULES'),('OPT-PAN-026','GRP-PAN-PHOTO','DOC-PHOTO-SPEC',NULL,'ALL_INDIAN_CITIZENS','Two passport size color photos (3.5 x 2.5 cm) and applicant signature.','VERIFIED','SRC-ITD-PAN'),('OPT-PAN-027','GRP-PAN-INST-EKYC','DOC-AADHAAR','RUL-PAN-004','INDIVIDUAL_ADULT','Direct e-KYC authentication via Aadhaar OTP (no paper or manual upload required).','VERIFIED','SRC-ITD-EPAN'),('OPT-UID-001','GRP-UID-ENR-POI','DOC-PASSPORT',NULL,'ALL_RESIDENTS','Indian Passport.','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-002','GRP-UID-ENR-POI','DOC-PAN',NULL,'ALL_RESIDENTS','PAN Card.','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-003','GRP-UID-ENR-POI','DOC-RATION',NULL,'ALL_RESIDENTS','Ration / PDS card with applicant photo.','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-004','GRP-UID-ENR-POI','DOC-VOTER-ID',NULL,'ALL_RESIDENTS','Voter Identity Card (EPIC).','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-005','GRP-UID-ENR-POI','DOC-DL',NULL,'ALL_RESIDENTS','Driving Licence.','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-006','GRP-UID-ENR-POI','DOC-UIDAI-STDFORM',NULL,'NO_STANDARD_DOC','UIDAI Standard Certificate issued by Gazetted Officer Group A or Tehsildar.','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-007','GRP-UID-ENR-POA','DOC-PASSPORT',NULL,'ALL_RESIDENTS','Indian Passport.','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-008','GRP-UID-ENR-POA','DOC-PASSBOOK',NULL,'ALL_RESIDENTS','Bank Passbook with photo & bank stamp.','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-009','GRP-UID-ENR-POA','DOC-RATION',NULL,'ALL_RESIDENTS','Ration card with address.','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-010','GRP-UID-ENR-POA','DOC-VOTER-ID',NULL,'ALL_RESIDENTS','Voter Identity Card.','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-011','GRP-UID-ENR-POA','DOC-UTIL',NULL,'ALL_RESIDENTS','Electricity / water / gas bill (not older than 3 months).','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-012','GRP-UID-ENR-POA','DOC-RENT',NULL,'TENANTS','Registered rent / lease agreement registered with Sub-Registrar.','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-013','GRP-UID-ENR-POA','DOC-UIDAI-STDFORM',NULL,'NO_STANDARD_DOC','UIDAI Standard Certificate issued by Gazetted Officer / Village Panchayat Head (for rural areas).','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-014','GRP-UID-ENR-DOB','DOC-BIRTH',NULL,'ALL_RESIDENTS','Birth certificate from competent municipal / Registrar authority.','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-015','GRP-UID-ENR-DOB','DOC-PASSPORT',NULL,'ALL_RESIDENTS','Passport.','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-016','GRP-UID-ENR-DOB','DOC-PAN',NULL,'ALL_RESIDENTS','PAN Card.','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-017','GRP-UID-ENR-DOB','DOC-EDU',NULL,'MATRICULATES','Class X / XII marksheet containing date of birth.','VERIFIED','SRC-UIDAI-DOCS'),('OPT-UID-018','GRP-UID-UPD-POA','DOC-PASSPORT','RUL-UID-003','ALL_RESIDENTS','Passport with updated address.','VERIFIED','SRC-UIDAI-MYAADHAAR'),('OPT-UID-019','GRP-UID-UPD-POA','DOC-UTIL','RUL-UID-003','ALL_RESIDENTS','Electricity / water / piped gas bill (not older than 3 months).','VERIFIED','SRC-UIDAI-MYAADHAAR'),('OPT-UID-020','GRP-UID-UPD-POA','DOC-BANK-STMT','RUL-UID-003','ALL_RESIDENTS','Bank account statement with stamp and signature (not older than 3 months).','VERIFIED','SRC-UIDAI-MYAADHAAR'),('OPT-UID-021','GRP-UID-UPD-POA','DOC-RENT','RUL-UID-003','TENANTS','Registered rent agreement registered with Sub-Registrar.','VERIFIED','SRC-UIDAI-MYAADHAAR'),('OPT-UID-022','GRP-UID-UPD-POA','DOC-HOF-DECL','RUL-UID-003','FAMILY_DEPENDENT','Head of Family (HOF) consent and declaration where applicant lacks document.','VERIFIED','SRC-UIDAI-MYAADHAAR'),('OPT-UID-023','GRP-UID-UPD-POI','DOC-PASSPORT','RUL-UID-005','ALL_RESIDENTS','Passport in updated name.','VERIFIED','SRC-UIDAI-CIRCULAR'),('OPT-UID-024','GRP-UID-UPD-POI','DOC-PAN','RUL-UID-005','ALL_RESIDENTS','PAN Card in updated name.','VERIFIED','SRC-UIDAI-CIRCULAR'),('OPT-UID-025','GRP-UID-UPD-POI','DOC-GAZETTE','RUL-UID-005','MAJOR_NAME_CHANGE','Official Gazette Notification for complete legal name change.','VERIFIED','SRC-UIDAI-CIRCULAR'),('OPT-UID-026','GRP-UID-UPD-POI','DOC-MARRIAGE-CERT','RUL-UID-005','AFTER_MARRIAGE','Marriage Certificate for post-marriage change in name / surname.','VERIFIED','SRC-UIDAI-CIRCULAR'),('OPT-UID-027','GRP-UID-UPD-DOB','DOC-BIRTH','RUL-UID-006','ALL_RESIDENTS','Birth certificate from competent municipal authority (UIDAI restricted list).','VERIFIED','SRC-UIDAI-CIRCULAR'),('OPT-UID-028','GRP-UID-UPD-DOB','DOC-PASSPORT','RUL-UID-006','ALL_RESIDENTS','Passport (accepted for DOB correction).','VERIFIED','SRC-UIDAI-CIRCULAR'),('OPT-VOT-001','GRP-VOT-PHOTO','DOC-PHOTO-SPEC',NULL,'ALL_APPLICANTS','Recent unsigned colour passport-size photograph, 4.5 x 3.5 cm, frontal face, white background.','VERIFIED','SRC-ECI-FORM6'),('OPT-VOT-002','GRP-VOT-AGE','DOC-BIRTH','RUL-VOT-002','ALL_APPLICANTS','Self-attested copy of Birth certificate from municipal authority / Registrar.','VERIFIED','SRC-ECI-FORM6'),('OPT-VOT-003','GRP-VOT-AGE','DOC-AADHAAR','RUL-VOT-002','ALL_APPLICANTS','Aadhaar card copy. Aadhaar number itself is voluntary on Form 6.','VERIFIED','SRC-ECI-FORM6'),('OPT-VOT-004','GRP-VOT-AGE','DOC-PAN','RUL-VOT-002','ALL_APPLICANTS','Self-attested PAN card copy. Listed as age/DOB proof.','VERIFIED','SRC-ECI-FORM6'),('OPT-VOT-005','GRP-VOT-AGE','DOC-DL','RUL-VOT-002','ALL_APPLICANTS','Self-attested Driving licence copy.','VERIFIED','SRC-ECI-FORM6'),('OPT-VOT-006','GRP-VOT-AGE','DOC-EDU','RUL-VOT-002','ALL_APPLICANTS','Class X / XII certificate containing date of birth.','VERIFIED','SRC-ECI-FORM6'),('OPT-VOT-007','GRP-VOT-AGE','DOC-PASSPORT','RUL-VOT-002','ALL_APPLICANTS','Self-attested Indian passport copy.','VERIFIED','SRC-ECI-FORM6'),('OPT-VOT-008','GRP-VOT-RES','DOC-UTIL','RUL-VOT-003','ALL_APPLICANTS','Water / electricity / gas connection bill for the address (at least 1 year).','VERIFIED','SRC-ECI-FORM6'),('OPT-VOT-009','GRP-VOT-RES','DOC-AADHAAR','RUL-VOT-003','ALL_APPLICANTS','Aadhaar card containing current ordinary residence address.','VERIFIED','SRC-ECI-FORM6'),('OPT-VOT-010','GRP-VOT-RES','DOC-PASSBOOK','RUL-VOT-003','ALL_APPLICANTS','Current passbook of nationalized / scheduled commercial bank or post office.','VERIFIED','SRC-ECI-FORM6'),('OPT-VOT-011','GRP-VOT-RES','DOC-PASSPORT','RUL-VOT-003','ALL_APPLICANTS','Valid Indian passport containing current residence address.','VERIFIED','SRC-ECI-FORM6'),('OPT-VOT-012','GRP-VOT-RES','DOC-LAND','RUL-VOT-003','ALL_APPLICANTS','Revenue Department land-ownership record including Kisan Bahi.','VERIFIED','SRC-ECI-FORM6'),('OPT-VOT-013','GRP-VOT-RES','DOC-RENT','RUL-VOT-003','TENANT','Registered rent or lease deed for tenants.','VERIFIED','SRC-ECI-FORM6'),('OPT-VOT-014','GRP-VOT-RES','DOC-SALE','RUL-VOT-003','PROPERTY_OWNER','Registered sale deed for house owners.','VERIFIED','SRC-ECI-FORM6');
