INSERT INTO `service_centers` VALUES ('CTR-GJ-ASK-001','UIDAI Aadhaar Seva Kendra (ASK), Ahmedabad','Aadhaar Enrolment & Update Center','Unique Identification Authority of India (UIDAI)','1st Floor, Krishna Complex, Opposite Choice Restaurant, Near Municipal Market, C.G. Road, Navrangpura','Ahmedabad','Ahmedabad','Gujarat','380009',23.0338,72.5562,'1947','Mon-Sun: 09:30 - 17:30 (Closed on Public Holidays)','https://appointments.uidai.gov.in/','2026-10-27 00:00:00','VERIFIED','UIDAI-operated standalone mega Aadhaar Seva Kendra. Supports all enrolment, demographic, biometric, and document update services with official token appointments and walk-ins.'),('CTR-GJ-ASK-002','UIDAI Aadhaar Seva Kendra (ASK), Vadodara','Aadhaar Enrolment & Update Center','Unique Identification Authority of India (UIDAI)','Ground Floor, Sears Tower, Near Pancham Highline, Sevasi Canal Road, Gotri','Vadodara','Vadodara','Gujarat','390021',22.3168,73.1412,'1947','Mon-Sun: 09:30 - 17:30 (Closed on Public Holidays)','https://appointments.uidai.gov.in/','2026-10-27 00:00:00','VERIFIED','UIDAI direct-run facility offering automated token queuing, wheelchair accessibility, biometric enrolment, and mandatory photo/iris/fingerprint updates.'),('CTR-GJ-ASK-003','UIDAI Aadhaar Seva Kendra (ASK), Surat','Aadhaar Enrolment & Update Center','Unique Identification Authority of India (UIDAI)','Shop No. 101-105, 1st Floor, International Commerce Centre (ICC), Ring Road, Majura Gate','Surat','Surat','Gujarat','395002',21.1812,72.8205,'1947','Mon-Sun: 09:30 - 17:30 (Closed on Public Holidays)','https://appointments.uidai.gov.in/','2026-10-27 00:00:00','VERIFIED','Official UIDAI-operated centre for South Gujarat. Online appointment booking recommended via myAadhaar portal.'),('CTR-GJ-ERO-001','Electoral Registration Office (ERO) - 44-Ellisbridge AC','Voter Service Office / ERO Office','Election Commission of India / Chief Electoral Officer, Gujarat','Prant Office / City Taluka Mamlatdar Office Compound, Near Old Collector Office, Bhadra','Ahmedabad','Ahmedabad','Gujarat','380001',23.0258,72.5802,'1950','Mon-Sat: 10:30 - 18:10 (2nd & 4th Sat and Govt Holidays closed)','https://ceo.gujarat.gov.in/','2026-10-27 00:00:00','VERIFIED','Constituency ERO/AERO office for Assembly Constituency 44. Accepts physical Form 6, claims, and objections. Assisted voter helpline desk active.'),('CTR-GJ-PO-001','Ahmedabad General Post Office (GPO) - Aadhaar & Citizen Counter','Post Office Citizen Service Center','Department of Posts, Gujarat Circle / UIDAI Registrar','Salapas Road, Near Relief Road, Opposite Victoria Garden, Bhadra','Ahmedabad','Ahmedabad','Gujarat','380001',23.0272,72.5835,'079-25507490','Mon-Sat: 10:00 - 16:30 (Sunday and Postal Holidays closed)','https://www.indiapost.gov.in/','2026-10-27 00:00:00','VERIFIED','Department of Posts designated Aadhaar counter. Handles new Aadhaar enrolment, mandatory biometric updates (age 5/15), and mobile/email updates.'),('CTR-GJ-TIN-001','Protean TIN-Facilitation Center / PAN Center, Ahmedabad','PAN Service Center (TIN-FC)','Protean eGov Technologies Limited / Income Tax Department','Office No. 204, 2nd Floor, Sakar-III, Near Income Tax Circle, Ashram Road','Ahmedabad','Ahmedabad','Gujarat','380014',23.0416,72.5714,'020-27218080','Mon-Fri: 10:00 - 18:00; Sat: 10:00 - 14:00','https://www.tin-nsdl.com/tin-facilities.html','2026-10-27 00:00:00','VERIFIED','Authorised Protean TIN-FC center code 38102. Physical submission of Form 49A, biometric e-KYC assistance, and document verification for PAN allotment.'),('DEMO-CENTER-001','[DEMO] Gandhinagar Citizen Facilitation Center (Jan Seva Kendra)','Integrated Citizen Service Center (Demo)','District Collectorate Gandhinagar (Simulated Prototype Entity)','Jan Seva Kendra Compound, Sector 11, Near District Court','Gandhinagar','Gandhinagar','Gujarat','382011',23.2156,72.6369,'079-23220000','Mon-Fri: 10:30 - 17:30','https://digitalgujarat.gov.in/','2026-10-27 00:00:00','DEMO_ONLY','Demonstration record for multi-service integration prototype testing. Simulates co-located counter for Voter ID physical receipts and PAN assistance in Gandhinagar.');
