INSERT INTO `service_routes` VALUES ('SRT-PAN-001','SVC-PAN-INSTANT','Income Tax Instant e-PAN Portal','online','Income Tax Department','https://www.incometax.gov.in/iec/foportal/instant-e-pan',NULL,'Direct Paperless Aadhaar e-KYC',0,0,'Gujarat & Pan-India (Indian individual residents)','NOT_INTEGRATED','Citizen visits official ITD e-Filing portal, enters Aadhaar number, verifies OTP on Aadhaar-linked mobile, confirms demographic details, and downloads instant e-PAN PDF within minutes.','SRC-ITD-EPAN','VERIFIED','2026-10-27 00:00:00','Completely digital paperless allotment. Requires Aadhaar with correct mobile number linked and applicant never previously allotted PAN.'),('SRT-PAN-002','SVC-PAN-NEW-IND','Protean (NSDL) Paperless Aadhaar e-KYC Route','online','Income Tax Department (administered via Protean eGov)','https://www.onlineservices.nsdl.com/paam/endUserRegisterContact.html',NULL,'Online e-KYC / e-Sign Submission',0,0,'Gujarat & Pan-India','NOT_INTEGRATED','Applicant selects Form 49A on Protean portal, completes personal data, verifies identity via UIDAI biometric/OTP e-Sign, pays statutory fee online, and receives acknowledgement number.','SRC-NSDL-PAN','VERIFIED','2026-10-27 00:00:00','Online submission route. External payment and e-Sign integration hosted solely on Protean gateway.'),('SRT-PAN-003','SVC-PAN-NEW-IND','Protean TIN-Facilitation Center Physical Submission','offline','Protean eGov Technologies / Income Tax Department','https://www.tin-nsdl.com/tin-facilities.html',NULL,'In-Person Assisted Paper Submission',0,1,'Gujarat (Authorized TIN-FC centers across Gujarat districts)','NOT_INTEGRATED','Citizen visits authorized TIN-FC (e.g. Ashram Road, Ahmedabad), submits filled Form 49A with 2 physical photos, pays fee at counter, and obtains printed acknowledgment slip.','SRC-NSDL-PAN','VERIFIED','2026-10-27 00:00:00','Physical paper route. Essential for applicants unable to complete paperless OTP e-KYC.'),('SRT-UID-001','SVC-UID-ENROL','UIDAI Aadhaar Seva Kendra In-Person Enrolment','hybrid','Unique Identification Authority of India (UIDAI)','https://uidai.gov.in/','https://appointments.uidai.gov.in/','Online Appointment Booking + Physical Visit',1,1,'Gujarat (UIDAI ASKs and Enrolment Centers)','NOT_INTEGRATED','Citizen books appointment online at appointments.uidai.gov.in, visits chosen ASK in Gujarat (e.g. Navrangpura Ahmedabad), presents original documents, gives biometric scans, and collects Enrolment Slip.','SRC-UIDAI-ENROL','VERIFIED','2026-10-27 00:00:00','Physical attendance is statutory for capturing photograph, 10 fingerprints, and iris scans. First-time enrolment is free.'),('SRT-UID-002','SVC-UID-UPD-ADDR','myAadhaar Online Address Update Portal','online','Unique Identification Authority of India (UIDAI)','https://myaadhaar.uidai.gov.in/',NULL,'Direct Self-Service Portal (OTP Based)',0,0,'Gujarat & Pan-India','NOT_INTEGRATED','Citizen logs in to myAadhaar with OTP, enters new residential address, uploads valid POA document scan (or initiates HOF consent), pays Rs 50 statutory fee, and tracks Service Request Number (SRN).','SRC-UIDAI-MYAADHAAR','VERIFIED','2026-10-27 00:00:00','Self-service digital update. Strictly limited to address update; cannot be used for demographic identity or biometric modifications.'),('SRT-UID-003','SVC-UID-UPD-DEMO','Aadhaar Seva Kendra In-Person Demographic Update','hybrid','Unique Identification Authority of India (UIDAI)','https://uidai.gov.in/','https://appointments.uidai.gov.in/','Appointment Booking + Physical Biometric Verification',1,1,'Gujarat (ASKs and Designated Centers)','NOT_INTEGRATED','Resident reserves slot online or takes walk-in token at ASK, submits correction form for Name/DOB/Gender with original documentary evidence, verifies fingerprint/iris auth, and pays statutory fee.','SRC-UIDAI-CIRCULAR','VERIFIED','2026-10-27 00:00:00','Statutory in-person requirement to verify identity and prevent identity duplication. Subject to UIDAI update frequency limits.'),('SRT-UID-004','SVC-UID-UPD-MOB','Aadhaar Seva Kendra In-Person Mobile Linking','hybrid','Unique Identification Authority of India (UIDAI)','https://uidai.gov.in/','https://appointments.uidai.gov.in/','Appointment Booking + Physical Biometric Authentication',1,1,'Gujarat (ASKs and Post Office Centers)','NOT_INTEGRATED','Citizen visits ASK or Post Office counter in Gujarat, provides mobile number, undergoes resident biometric authentication, pays Rs 50 fee, and obtains update receipt.','SRC-UIDAI-ENROL','VERIFIED','2026-10-27 00:00:00','No documentary proof required for mobile/email update, but physical attendance and biometric verification are mandatory.'),('SRT-UID-005','SVC-UID-UPD-BIO','Aadhaar Seva Kendra Biometric Update Route','hybrid','Unique Identification Authority of India (UIDAI)','https://uidai.gov.in/','https://appointments.uidai.gov.in/','Appointment Booking + In-Person Biometric Capture',1,1,'Gujarat (UIDAI ASKs across Gujarat)','NOT_INTEGRATED','Resident schedules appointment via UIDAI portal, attends ASK in Gujarat, completes live capture of facial photo, all 10 fingerprints, and both irises. Mandatory updates for children at 5 and 15 are free.','SRC-UIDAI-ENROL','VERIFIED','2026-10-27 00:00:00','Physical attendance is mandatory. DigiSahay directs citizens to official booking portal without direct internal booking integration.'),('SRT-UID-006','SVC-UID-DOC-UPD','myAadhaar Online Document Re-validation Route','online','Unique Identification Authority of India (UIDAI)','https://myaadhaar.uidai.gov.in/',NULL,'Direct Self-Service Document Re-validation',0,0,'Gujarat & Pan-India','NOT_INTEGRATED','Citizen logs in to myAadhaar portal, reviews demographic details, uploads latest POI and POA identity documents to strengthen database accuracy under Aadhaar Regulation 16A.','SRC-UIDAI-MYAADHAAR','VERIFIED','2026-10-27 00:00:00','Self-service online portal. Free re-validation periods often extended by UIDAI; does not alter existing demographic data without separate update request.'),('SRT-VOT-001','SVC-VOTER-NEW','ECI Voters Service Portal (Online Form 6)','online','Election Commission of India (ECI)','https://voters.eci.gov.in/',NULL,'Direct Official Web Portal',0,0,'Gujarat (Constituency specific electoral roll)','NOT_INTEGRATED','Citizen logs in to voters.eci.gov.in using mobile OTP, selects Form 6, fills declaration, uploads photo and self-attested proofs of age and ordinary residence, and receives reference acknowledgment.','SRC-ECI-VSP','VERIFIED','2026-10-27 00:00:00','DigiSahay guides document readiness and eligibility; submission is strictly conducted on official ECI portal. No authorized direct API integration.'),('SRT-VOT-002','SVC-VOTER-NEW','In-Person ERO Office Physical Submission','offline','Chief Electoral Officer Gujarat / ERO','https://ceo.gujarat.gov.in/',NULL,'Physical Walk-In Submission',0,1,'Constituency Specific (Gujarat Assembly Constituencies)','NOT_INTEGRATED','Citizen downloads or collects paper Form 6 from local ERO/AERO office in Gujarat (e.g., Bhadra, Ahmedabad), attaches physical photocopies of age and address proofs, and signs submission.','SRC-ECI-FAQ','VERIFIED','2026-10-27 00:00:00','Physical offline submission route. No appointment booking required by election authority; walk-in during office working hours.');
/*!40000 ALTER TABLE `service_routes` ENABLE KEYS */;
