INSERT INTO `services` VALUES ('SVC-PAN-CHANGE','Changes or Correction in PAN Data / Reprint of PAN Card','PAN Card','CORRECTION_AND_REPRINT','CSF Form','Request for changes/corrections in PAN card details or reissuance/reprint of existing PAN.','Income Tax Department (Protean / UTIITSL)','https://www.onlineservices.nsdl.com/',0,'OUT_OF_SCOPE'),('SVC-PAN-INSTANT','Instant e-PAN Allotment (via Aadhaar e-KYC)','PAN Card','NEW_ALLOTMENT','Paperless Digital','Paperless, free, instant allotment of digital e-PAN for adult resident individuals possessing valid Aadhaar with linked mobile.','Income Tax Department (e-Filing Portal)','https://www.incometax.gov.in/iec/foportal/instant-e-pan',1,'VERIFIED'),('SVC-PAN-NEW-IND','New PAN Allotment (Indian Citizen / Resident Individual)','PAN Card','NEW_ALLOTMENT','Form 49A','Application for allotment of a Permanent Account Number for Indian citizens and HUF.','Income Tax Department (administered via Protean eGov / UTIITSL)','https://www.onlineservices.nsdl.com/paam/endUserRegisterContact.html',1,'VERIFIED'),('SVC-PAN-NEW-NRI','New PAN Allotment (Foreign Citizen / Non-Resident)','PAN Card','NEW_ALLOTMENT','Form 49AA','Application for allotment of PAN for foreign citizens, entities, or entities incorporated outside India.','Income Tax Department (administered via Protean / UTIITSL)','https://www.utiitsl.com/',0,'OUT_OF_SCOPE'),('SVC-UID-DOC-UPD','Aadhaar Document Update (Re-validation of POI & POA)','Aadhaar Card','DOCUMENT_VERIFICATION','myAadhaar Portal','Periodic submission of current Proof of Identity and Proof of Address for Aadhaar holders whose Aadhaar was issued >10 years ago.','Unique Identification Authority of India (UIDAI)','https://myaadhaar.uidai.gov.in/',1,'VERIFIED'),('SVC-UID-ENROL','New Aadhaar Enrolment','Aadhaar Card','NEW_ENROLMENT','Aadhaar Enrolment Form','Initial enrolment for biometric and demographic capture to generate a 12-digit Aadhaar number (always free).','Unique Identification Authority of India (UIDAI)','https://bhuvan-app3.nrsc.gov.in/aadhaar/',1,'VERIFIED'),('SVC-UID-UPD-ADDR','Aadhaar Address Update (Online / Document or HOF)','Aadhaar Card','DEMOGRAPHIC_UPDATE','Online Update / Form','Update of residential address via myAadhaar portal using valid Address Proof or Head of Family (HOF) consent, or offline at ASK.','Unique Identification Authority of India (UIDAI)','https://myaadhaar.uidai.gov.in/',1,'VERIFIED'),('SVC-UID-UPD-BIO','Aadhaar Biometric Update (Mandatory / Voluntary)','Aadhaar Card','BIOMETRIC_UPDATE','Aadhaar Update Form','Update of iris, ten fingerprints, and facial photograph. Mandatory for children aged 5-7 and 15-17 (free of cost); voluntary for adults upon fee.','Unique Identification Authority of India (UIDAI)','https://appointments.uidai.gov.in/',1,'VERIFIED'),('SVC-UID-UPD-DEMO','Aadhaar Demographic Update (Name, DOB, Gender - In-Person)','Aadhaar Card','DEMOGRAPHIC_UPDATE','Aadhaar Update Form','Correction/update of Name (max 2 times), Date of Birth (max 1 time), or Gender (max 1 time). Mandatory in-person visit to ASK/Aadhaar Kendra.','Unique Identification Authority of India (UIDAI)','https://appointments.uidai.gov.in/',1,'VERIFIED'),('SVC-UID-UPD-MOB','Aadhaar Mobile Number / Email Linking or Update','Aadhaar Card','CONTACT_UPDATE','Aadhaar Update Form','Registering or updating active mobile number or email ID in Aadhaar record. Requires in-person biometric authentication at ASK or via IPPB Doorstep Postman.','Unique Identification Authority of India (UIDAI)','https://appointments.uidai.gov.in/',1,'VERIFIED'),('SVC-VOTER-CORR','Correction of Entries in Electoral Roll','Voter ID','CORRECTION','Form 8','Correction of name, age, address, photograph or EPIC replacement in electoral roll.','Election Commission of India (ECI); ERO','https://voters.eci.gov.in/',0,'OUT_OF_SCOPE'),('SVC-VOTER-DEL','Deletion or Objection to Electoral Entry','Voter ID','DELETION','Form 7','Objection against entry or application for deletion of deceased / shifted voter.','Election Commission of India (ECI); ERO','https://voters.eci.gov.in/',0,'OUT_OF_SCOPE'),('SVC-VOTER-EPIC','Replacement EPIC Card','Voter ID','REPLACEMENT','Form 8','Issue of replacement Voter ID card without alteration in electoral entries.','Election Commission of India (ECI); ERO','https://voters.eci.gov.in/',0,'OUT_OF_SCOPE'),('SVC-VOTER-NEW','New Voter Registration (General Elector)','Voter ID','NEW_REGISTRATION','Form 6','Enrolment of a first-time elector in the electoral roll for Indian citizens aged 18+.','Election Commission of India (ECI); ERO / AERO / BLO','https://voters.eci.gov.in/',1,'VERIFIED'),('SVC-VOTER-OVS','Overseas Elector Registration','Voter ID','NEW_REGISTRATION','Form 6A','Registration in electoral roll for non-resident Indian citizens living abroad.','Election Commission of India (ECI); ERO','https://voters.eci.gov.in/',0,'OUT_OF_SCOPE'),('SVC-VOTER-SHIFT','Shifting of Residence','Voter ID','SHIFTING','Form 8','Move existing voter registration within or outside the Assembly Constituency.','Election Commission of India (ECI); ERO','https://voters.eci.gov.in/',0,'OUT_OF_SCOPE');
