INSERT INTO `sources` VALUES ('SRC-ECI-FAQ','ECI Voter Registration FAQs','Election Commission of India','https://www.eci.gov.in/faq/en/how-to-register','OFFICIAL_FAQ','Eligibility criteria, 4 qualifying dates, submission routes, 1950 helpline','2026-10-27 00:00:00','2026-10-27 00:00:00','VERIFIED','Official guidance on voter enrollment and ERO powers.'),('SRC-ECI-FORM6','ECI Form 6 Application & Guidelines','Election Commission of India','https://voters.eci.gov.in/formspdf/Form_6_English.pdf','STATUTORY_FORM','Instructions on page 2-4: accepted age and address proofs, declaration','2026-10-27 00:00:00','2026-10-27 00:00:00','VERIFIED','Primary statutory form under Registration of Electors Rules 1960.'),('SRC-ECI-MYTH','ECI Myth vs Reality on Aadhaar-Voter Linking','Election Commission of India','https://www.eci.gov.in/mythvsreality/details','OFFICIAL_CLARIFICATION','Voluntary nature of Aadhaar in Form 6; non-submission not grounds for rejection','2026-10-27 00:00:00','2026-10-27 00:00:00','VERIFIED','Official clarification that Aadhaar collection in Form 6 is purely voluntary.'),('SRC-ECI-VSP','ECI Voters Service Portal','Election Commission of India','https://voters.eci.gov.in/','OFFICIAL_PORTAL','Citizen registration workflow, e-EPIC download, reference tracking','2026-10-27 00:00:00','2026-10-27 00:00:00','VERIFIED','Primary digital portal for electoral services.'),('SRC-IPPB-AADHAAR','India Post Payments Bank Aadhaar Services','Department of Posts / IPPB','https://www.ippbonline.com/web/ippb/aadhaar-services','OFFICIAL_PORTAL','Child Aadhaar enrolment and Doorstep Mobile Number Update via Postman','2026-10-27 00:00:00','2026-10-27 00:00:00','VERIFIED','Authorized doorstep delivery channel for Aadhaar mobile linking.'),('SRC-ITD-EPAN','Income Tax e-Filing Instant e-PAN Service','Income Tax Department','https://www.incometax.gov.in/iec/foportal/instant-e-pan','OFFICIAL_PORTAL','Aadhaar e-KYC instant PAN issuance rules, eligibility, limitations','2026-10-27 00:00:00','2026-10-27 00:00:00','VERIFIED','Primary service for instantaneous free digital PAN allotment.'),('SRC-ITD-PAN','Income Tax Department PAN Allotment Overview','Income Tax Department','https://incometaxindia.gov.in/Pages/tax-services/apply-for-pan.aspx','OFFICIAL_PORTAL','Application procedures, authorized service agencies, guidelines','2026-10-27 00:00:00','2026-10-27 00:00:00','VERIFIED','Primary tax department portal for PAN information.'),('SRC-ITD-RULES','Income-tax Rules 1962 (Rule 114)','Income Tax Department (CBDT)','https://incometaxindia.gov.in/pages/rules/income-tax-rules-1962.aspx','STATUTORY_RULE','Rule 114 & Form 49A: List of accepted documents for POI, POA, DOB','2026-10-27 00:00:00','2026-10-27 00:00:00','VERIFIED','Statutory foundation specifying exact documents accepted for PAN allotment.'),('SRC-NSDL-PAN','Protean eGov (formerly NSDL) PAN Services','Protean eGov Technologies Limited','https://www.onlineservices.nsdl.com/paam/endUserRegisterContact.html','OFFICIAL_SERVICE_PROVIDER','Online Form 49A submission, paperless e-Sign, application fee schedule','2026-10-27 00:00:00','2026-10-27 00:00:00','VERIFIED','Authorized PAN service entity appointed by Income Tax Department.'),('SRC-UIDAI-ACT','Aadhaar (Targeted Delivery of Financial Subsidies) Act 2016 & Regs','UIDAI / Ministry of Electronics & IT','https://uidai.gov.in/en/about-uidai/legal-framework.html','STATUTORY_ACT','Section 3: Enrolment, eligibility (182 days residency), biometric regulations','2026-10-27 00:00:00','2026-10-27 00:00:00','VERIFIED','Governing statutory legislation for Aadhaar generation.'),('SRC-UIDAI-CIRCULAR','UIDAI Circular on Limits of Demographic Updates','Unique Identification Authority of India','https://uidai.gov.in/en/my-aadhaar/about-your-aadhaar/updating-data-on-aadhaar.html','OFFICIAL_CIRCULAR','Frequency limits: Name (2 times), DOB (1 time), Gender (1 time)','2026-10-27 00:00:00','2026-10-27 00:00:00','VERIFIED','Policy establishing strict lifetime thresholds for updating demographic fields.'),('SRC-UIDAI-DOCS','UIDAI Valid Supporting Documents List','Unique Identification Authority of India','https://uidai.gov.in/images/commDoc/26_JAN_2023_Aadhaar_List_of_supporting_document_English.pdf','OFFICIAL_DOCUMENT_LIST','Annexure A & B: Permissible POI, POA, DOB, POR documents and standard format','2026-10-27 00:00:00','2026-10-27 00:00:00','VERIFIED','Primary authoritative document list for Aadhaar enrolment and update.'),('SRC-UIDAI-ENROL','UIDAI Aadhaar Seva Kendra & Appointment Booking','Unique Identification Authority of India','https://appointments.uidai.gov.in/','OFFICIAL_PORTAL','Locate enrolment centre, book appointment, offline services fee schedule','2026-10-27 00:00:00','2026-10-27 00:00:00','VERIFIED','Appointment system and authorized centre locator for physical visits.'),('SRC-UIDAI-MYAADHAAR','UIDAI myAadhaar Citizen Portal','Unique Identification Authority of India','https://myaadhaar.uidai.gov.in/','OFFICIAL_PORTAL','Online Address Update, Document Update, Download Aadhaar, Order PVC Card','2026-10-27 00:00:00','2026-10-27 00:00:00','VERIFIED','Citizen self-service portal for online updates.'),('SRC-UTIITSL-PAN','UTIITSL PAN Services Portal','UTI Infrastructure Technology And Services Limited','https://www.utiitsl.com/UTIITSL_SITE/panindex.html','OFFICIAL_SERVICE_PROVIDER','Online and offline PAN application processing, PSA network','2026-10-27 00:00:00','2026-10-27 00:00:00','VERIFIED','Authorized PAN service agency appointed by Income Tax Department.');
