INSERT INTO `submission_routes` VALUES ('RTE-PAN-001','SVC-PAN-NEW-IND','ONLINE_PAPERLESS','Protean (NSDL) Paperless e-KYC Application','https://www.onlineservices.nsdl.com/paam/endUserRegisterContact.html','Fill Form 49A online, authenticate through Aadhaar OTP (e-KYC & e-Sign). No physical document dispatch required. Fee: Rs. 107 (physical card dispatched) or Rs. 72 (e-PAN only).',0,0,'PAN_INDIA','VERIFIED','SRC-NSDL-PAN'),('RTE-PAN-002','SVC-PAN-NEW-IND','ONLINE_PAPERLESS','UTIITSL Paperless Aadhaar e-KYC Route','https://www.utiitsl.com/UTIITSL_SITE/panindex.html','Complete digital Form 49A application via UTIITSL portal using Aadhaar authentication. Entirely online and paperless.',0,0,'PAN_INDIA','VERIFIED','SRC-UTIITSL-PAN'),('RTE-PAN-003','SVC-PAN-NEW-IND','ONLINE_PHYSICAL_DISPATCH','Online Application with Scanned Documents / Physical Forwarding','https://www.onlineservices.nsdl.com/paam/endUserRegisterContact.html','Fill application online, upload scanned copies of documents and photo/signature, or print acknowledgement slip and mail physical copies to Protean Pune / UTIITSL centre.',0,0,'PAN_INDIA','VERIFIED','SRC-NSDL-PAN'),('RTE-PAN-004','SVC-PAN-NEW-IND','PHYSICAL_CENTRE','Authorised TIN-FC / PAN Centre / UTIITSL PSA','https://www.tin-nsdl.com/tin-facilities.html','Submit physical Form 49A with 2 photographs and self-attested copies of POI, POA, DOB at any authorised TIN Facilitation Centre across India.',0,1,'PAN_INDIA','VERIFIED','SRC-NSDL-PAN'),('RTE-PAN-005','SVC-PAN-INSTANT','ONLINE_PAPERLESS','Income Tax e-Filing Instant e-PAN Portal','https://www.incometax.gov.in/iec/foportal/instant-e-pan','Enter Aadhaar number, authenticate via Aadhaar-linked OTP, validate details, and download digital e-PAN in PDF instantly. Completely free of cost.',0,0,'PAN_INDIA','VERIFIED','SRC-ITD-EPAN'),('RTE-UID-001','SVC-UID-ENROL','PHYSICAL_CENTRE','Aadhaar Seva Kendra (ASK) / Enrolment Centre','https://appointments.uidai.gov.in/','Mandatory in-person visit for photo, 10-fingerprints, and iris scan capture with original POI/POA/DOB documents. Always free of cost. Online appointment booking available.',0,1,'PAN_INDIA','VERIFIED','SRC-UIDAI-ENROL'),('RTE-UID-002','SVC-UID-UPD-ADDR','ONLINE_PORTAL','UIDAI myAadhaar Web Portal','https://myaadhaar.uidai.gov.in/','Login with Aadhaar and OTP. Upload valid POA document or initiate HOF declaration. Standard fee: Rs. 50. Track status online via SRN.',0,0,'PAN_INDIA','VERIFIED','SRC-UIDAI-MYAADHAAR'),('RTE-UID-003','SVC-UID-UPD-DEMO','PHYSICAL_CENTRE','Aadhaar Seva Kendra (In-Person Demographic Update)','https://appointments.uidai.gov.in/','Mandatory physical visit to update Name, DOB, or Gender. Operator verifies original document and captures biometric authentication. Fee: Rs. 50.',0,1,'PAN_INDIA','VERIFIED','SRC-UIDAI-ENROL'),('RTE-UID-004','SVC-UID-UPD-MOB','PHYSICAL_CENTRE','Aadhaar Seva Kendra (Mobile / Email Update)','https://appointments.uidai.gov.in/','Mandatory physical visit for biometric authentication to link or update mobile number. No supporting document required. Fee: Rs. 50.',0,1,'PAN_INDIA','VERIFIED','SRC-UIDAI-ENROL'),('RTE-UID-005','SVC-UID-UPD-MOB','PHYSICAL_DOORSTEP','India Post Payments Bank (IPPB) Doorstep Service','https://www.ippbonline.com/web/ippb/aadhaar-services','Postman / Gramin Dak Sevak visits home with biometric tablet to update Aadhaar-linked mobile number via fingerprint authentication. Standard fee: Rs. 50.',0,1,'POSTAL_SERVICE_AREAS','VERIFIED','SRC-IPPB-AADHAAR'),('RTE-UID-006','SVC-UID-UPD-BIO','PHYSICAL_CENTRE','Aadhaar Seva Kendra (Biometric Update)','https://appointments.uidai.gov.in/','Physical visit for capture of fingerprints, iris, and facial photo. Free for mandatory updates for children (ages 5-7 & 15-17); Rs. 100 fee for voluntary adult updates.',0,1,'PAN_INDIA','VERIFIED','SRC-UIDAI-ENROL'),('RTE-UID-007','SVC-UID-DOC-UPD','ONLINE_PORTAL','myAadhaar Document Update Portal','https://myaadhaar.uidai.gov.in/','Online re-validation of POI and POA documents for Aadhaar holders (>10 years old). Currently provided free of charge on myAadhaar portal until notified date.',0,0,'PAN_INDIA','VERIFIED','SRC-UIDAI-MYAADHAAR'),('RTE-VOT-001','SVC-VOTER-NEW','ONLINE_PORTAL','ECI Voters Service Portal','https://voters.eci.gov.in/','Register/login on ECI portal, fill Form 6, upload photograph and self-attested proofs of age and address, submit and track via reference ID.',0,0,'PAN_INDIA','VERIFIED','SRC-ECI-VSP'),('RTE-VOT-002','SVC-VOTER-NEW','MOBILE_APP','ECI Voter Helpline App (VHA)','https://voters.eci.gov.in/','Download official VHA app on Android/iOS, navigate to Voter Services -> New Registration (Form 6), fill and submit digitally.',0,0,'PAN_INDIA','VERIFIED','SRC-ECI-VSP'),('RTE-VOT-003','SVC-VOTER-NEW','PHYSICAL_CENTRE','In-Person submission at ERO / AERO Office','https://www.eci.gov.in/faq/en/how-to-register','Obtain physical Form 6 free of cost, complete and sign, attach self-attested photocopies of proofs, submit directly to ERO/AERO of constituency.',0,1,'CONSTITUENCY_SPECIFIC','VERIFIED','SRC-ECI-FAQ'),('RTE-VOT-004','SVC-VOTER-NEW','PHYSICAL_DOORSTEP','Through Booth Level Officer (BLO)','https://www.eci.gov.in/faq/en/how-to-register','Hand over completed Form 6 with document copies to local BLO during doorstep enumeration drives or field visits.',0,1,'POLLING_STATION_AREA','VERIFIED','SRC-ECI-FAQ'),('RTE-VOT-005','SVC-VOTER-NEW','POSTAL_SERVICE','By Post to Concerned ERO','https://www.eci.gov.in/faq/2/9','Send signed Form 6 with self-attested documents by registered / speed post to the address of the concerned Electoral Registration Officer.',0,0,'PAN_INDIA','VERIFIED','SRC-ECI-FAQ'),('RTE-VOT-006','SVC-VOTER-NEW','HELPLINE','National Voter Helpline 1950','https://voters.eci.gov.in/','Toll-free telephonic helpline 1950 for voter registration guidance, booth queries, and application status tracking.',0,0,'PAN_INDIA','VERIFIED','SRC-ECI-FAQ');
